#include <vector>

// Generic helper that expects T& from operator[]. For std::vector<int>
// it's fine; for std::vector<bool> the [] returns a PROXY (vector<bool>::reference)
// not a bool& — so `auto& flag = v[3];` deduces to the proxy type, not bool&.
// Modifying `flag` modifies the bit, but a copy of `flag` does NOT, so generic
// code that takes `T&` ends up writing to a temporary.
template<typename T>
void set_third(std::vector<T>& v, T value) {
    auto& slot = v[3];  // for bool: proxy reference, NOT bool&.
    slot = value;
    // For bool, the next line is the trap:
    T copy_of_slot = slot;
    // `copy_of_slot` is now a *value*, not a reference into v's bit array.
    // If the caller relied on later modifications through slot, they're lost.
}
